-- Every local Service Layer write keeps its original payload, including any
-- property the local engine does not map to a column yet, so nothing is lost.
CREATE TABLE "LocalSlLog" (
  "LogId" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "Entity" TEXT NOT NULL,
  "ObjType" TEXT,
  "DocEntry" INTEGER,
  "Method" TEXT NOT NULL,
  "Payload" JSONB NOT NULL,
  "Unmapped" JSONB,
  "UserCode" TEXT,
  "CreatedAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX "IX_LocalSlLog_Doc" ON "LocalSlLog" ("ObjType", "DocEntry");
